def longest_palindrome(s):
    def expand(left, right):
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return s[left + 1:right]                                # the widest match found from this center

    best = ""
    for center in range(len(s)):
        odd = expand(center, center)                              # single character center
        even = expand(center, center + 1)                          # between two characters center
        for candidate in (odd, even):
            if len(candidate) > len(best):
                best = candidate
    return best


if __name__ == "__main__":
    s = "babad"
    print(longest_palindrome(s))

