public class Main {
    String longestPalindrome(String s) {
        if (s.isEmpty()) return "";
        StringBuilder sb = new StringBuilder("#");
        for (char ch : s.toCharArray()) sb.append(ch).append('#');   // insert separators for odd length palindromes
        String transformed = sb.toString();
        int n = transformed.length();
        int[] radius = new int[n];
        int center = 0, right = 0;
        for (int i = 0; i < n; i++) {
            if (i < right) {
                int mirror = 2 * center - i;
                radius[i] = Math.min(right - i, radius[mirror]);          // reuse the mirrored center's known radius
            }
            while (i - radius[i] - 1 >= 0 && i + radius[i] + 1 < n &&
                   transformed.charAt(i - radius[i] - 1) == transformed.charAt(i + radius[i] + 1)) {
                radius[i]++;                                                // only expand further if genuinely needed
            }
            if (i + radius[i] > right) { center = i; right = i + radius[i]; }
        }
        int maxRadius = 0, centerIndex = 0;
        for (int i = 0; i < n; i++) {
            if (radius[i] > maxRadius) { maxRadius = radius[i]; centerIndex = i; }
        }
        int start = (centerIndex - maxRadius) / 2;
        return s.substring(start, start + maxRadius);
    }

    public static void main(String[] args) {
        String s = "babad";
        Main solution = new Main();
        System.out.println(solution.longestPalindrome(s));
    }
}

